def occurrences(start, freq, interval, count, until, byweekday, exdates):
    from datetime import datetime, timedelta

    start_date = datetime.strptime(start, '%Y-%m-%d').date()
    until_date = None
    if until:
        until_date = datetime.strptime(until, '%Y-%m-%d').date()

    exdates_set = set(exdates) if exdates else set()

    candidates = []

    if freq == 'daily':
        k = 0
        while True:
            candidate = start_date + timedelta(days=k * interval)
            if until_date and candidate > until_date:
                break
            if count and len(candidates) >= count:
                break
            candidates.append(candidate)
            k += 1

    elif freq == 'weekly':
        start_weekday = start_date.weekday()
        if byweekday is None:
            byweekday = [start_weekday]
        byweekday = list(set(byweekday))

        k = 0
        while True:
            week_start = start_date - timedelta(days=start_weekday) + timedelta(weeks=k * interval)

            for day_offset in range(7):
                candidate = week_start + timedelta(days=day_offset)
                weekday = candidate.weekday()

                if candidate < start_date:
                    continue
                if until_date and candidate > until_date:
                    break
                if count and len(candidates) >= count:
                    break

                if weekday in byweekday:
                    candidates.append(candidate)

            if until_date and week_start + timedelta(days=6) > until_date:
                break
            if count and len(candidates) >= count:
                break

            k += 1

    elif freq == 'monthly':
        year = start_date.year
        month = start_date.month
        day = start_date.day

        k = 0
        while True:
            target_month = month + k * interval
            target_year = year + (target_month - 1) // 12
            target_month = (target_month - 1) % 12 + 1

            try:
                candidate = datetime(target_year, target_month, day).date()
            except ValueError:
                k += 1
                continue

            if until_date and candidate > until_date:
                break
            if count and len(candidates) >= count:
                break

            candidates.append(candidate)
            k += 1

    result = [d for d in candidates if d.strftime('%Y-%m-%d') not in exdates_set]
    result.sort()

    return [d.strftime('%Y-%m-%d') for d in result]

